[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "reservation-plan-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "reservation-plan-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "header"
              },
              {
                "id": "warning_card"
              },
              {
                "id": "summary_card"
              },
              {
                "id": "restaurant_image"
              },
              {
                "id": "details_tabs"
              },
              {
                "id": "actions_divider"
              },
              {
                "id": "quick_actions_header"
              },
              {
                "id": "actions_row"
              },
              {
                "id": "sources_divider"
              },
              {
                "id": "sources_header"
              },
              {
                "id": "source_link"
              }
            ]
          }
        },
        {
          "id": "header",
          "type": "Header",
          "properties": {
            "title": "Dinner Reservation Plan",
            "subtitle": "L'Ambroisie"
          }
        },
        {
          "id": "warning_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "warning_content"
            }
          }
        },
        {
          "id": "warning_content",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "warning_title_row"
              },
              {
                "id": "warning_text"
              }
            ]
          }
        },
        {
          "id": "warning_title_row",
          "type": "Row",
          "properties": {
            "spacing": "medium",
            "crossAxisAlignment": "center",
            "children": [
              {
                "id": "warning_icon"
              },
              {
                "id": "warning_title"
              }
            ]
          }
        },
        {
          "id": "warning_icon",
          "type": "Icon",
          "properties": {
            "name": "warning",
            "color": "warning"
          }
        },
        {
          "id": "warning_title",
          "type": "Text",
          "properties": {
            "text": "PENDING - ACTION REQUIRED",
            "style": "headline",
            "color": "warning"
          }
        },
        {
          "id": "warning_text",
          "type": "Text",
          "properties": {
            "text": "This confirmation is a template to guide your booking. A placeholder name (\"Ms. Jane Doe\") is used for the reservation. You must contact the restaurant directly to confirm availability and secure the booking, as a reservation for this date and time is extremely competitive and not guaranteed.",
            "style": "body"
          }
        },
        {
          "id": "summary_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "summary_content"
            }
          }
        },
        {
          "id": "summary_content",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "summary_title"
              },
              {
                "id": "summary_list"
              }
            ]
          }
        },
        {
          "id": "summary_title",
          "type": "Text",
          "properties": {
            "text": "Booking Confirmation Summary",
            "style": "title"
          }
        },
        {
          "id": "summary_list",
          "type": "List",
          "properties": {
            "children": [
              {
                "id": "item_restaurant"
              },
              {
                "id": "item_status"
              },
              {
                "id": "item_date"
              },
              {
                "id": "item_time"
              },
              {
                "id": "item_party"
              },
              {
                "id": "item_booked_under"
              },
              {
                "id": "item_ref_id"
              }
            ]
          }
        },
        {
          "id": "item_restaurant",
          "type": "ListItem",
          "properties": {
            "primary": "Restaurant",
            "secondary": "L'Ambroisie (*** Michelin)"
          }
        },
        {
          "id": "item_status",
          "type": "ListItem",
          "properties": {
            "primary": "Status",
            "secondary": "PENDING - ACTION REQUIRED"
          }
        },
        {
          "id": "item_date",
          "type": "ListItem",
          "properties": {
            "primary": "Date",
            "secondary": "Tuesday, 24 December 2024"
          }
        },
        {
          "id": "item_time",
          "type": "ListItem",
          "properties": {
            "primary": "Time",
            "secondary": "20:00 (8:00 PM)"
          }
        },
        {
          "id": "item_party",
          "type": "ListItem",
          "properties": {
            "primary": "Party Size",
            "secondary": "8 guests"
          }
        },
        {
          "id": "item_booked_under",
          "type": "ListItem",
          "properties": {
            "primary": "Booked Under",
            "secondary": "Ms. Jane Doe (Corporate Group)"
          }
        },
        {
          "id": "item_ref_id",
          "type": "ListItem",
          "properties": {
            "primary": "Reference ID",
            "secondary": "L'AMB-CORP-2412 (Provide when calling)"
          }
        },
        {
          "id": "restaurant_image",
          "type": "Image",
          "properties": {
            "src": "/images/153/000/101/711/original/ambroisie-bernard-pacaud-restaurant-paris-4.jpg",
            "altText": "L'Ambroisie, Place des Vosges",
            "aspectRatio": "16:9"
          }
        },
        {
          "id": "details_tabs",
          "type": "Tabs",
          "properties": {
            "tabs": [
              {
                "id": "tab_details"
              },
              {
                "id": "tab_policy"
              },
              {
                "id": "tab_next_steps"
              }
            ]
          }
        },
        {
          "id": "tab_details",
          "type": "Tab",
          "properties": {
            "label": "Details",
            "child": {
              "id": "details_content"
            }
          }
        },
        {
          "id": "details_content",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "address_header"
              },
              {
                "id": "address_text"
              },
              {
                "id": "request_header"
              },
              {
                "id": "request_text"
              },
              {
                "id": "budget_header"
              },
              {
                "id": "budget_text"
              }
            ]
          }
        },
        {
          "id": "address_header",
          "type": "Text",
          "properties": {
            "text": "Address",
            "style": "headline"
          }
        },
        {
          "id": "address_text",
          "type": "Text",
          "properties": {
            "text": "9 Place des Vosges, 75004 Paris, France",
            "style": "body"
          }
        },
        {
          "id": "request_header",
          "type": "Text",
          "properties": {
            "text": "Special Request",
            "style": "headline"
          }
        },
        {
          "id": "request_text",
          "type": "Text",
          "properties": {
            "text": "A quiet table suitable for business discussion has been requested for your group. Please reiterate this when confirming with the restaurant.",
            "style": "body"
          }
        },
        {
          "id": "budget_header",
          "type": "Text",
          "properties": {
            "text": "Budget Note",
            "style": "headline"
          }
        },
        {
          "id": "budget_text",
          "type": "Text",
          "properties": {
            "text": "The specified budget is €400 per person. L'Ambroisie's tasting menu and wine pairings may exceed this. It is highly recommended to discuss set menu options or pre-select wines with the sommelier in advance to align with your budget.",
            "style": "body"
          }
        },
        {
          "id": "tab_policy",
          "type": "Tab",
          "properties": {
            "label": "Cancellation Policy",
            "child": {
              "id": "policy_content"
            }
          }
        },
        {
          "id": "policy_content",
          "type": "Text",
          "properties": {
            "text": "A minimum of 48 hours' notice is required for cancellation or any changes to your reservation. Given this is a holiday booking for a large group, a deposit and a stricter cancellation policy may apply. Please verify the exact terms directly with the restaurant.",
            "style": "body"
          }
        },
        {
          "id": "tab_next_steps",
          "type": "Tab",
          "properties": {
            "label": "Next Steps",
            "child": {
              "id": "next_steps_list"
            }
          }
        },
        {
          "id": "next_steps_list",
          "type": "List",
          "properties": {
            "children": [
              {
                "id": "step_1"
              },
              {
                "id": "step_2"
              },
              {
                "id": "step_3"
              },
              {
                "id": "step_4"
              }
            ]
          }
        },
        {
          "id": "step_1",
          "type": "ListItem",
          "properties": {
            "leading": {
              "id": "step_1_num"
            },
            "primary": "Contact Restaurant Immediately",
            "secondary": "Call L'Ambroisie at your earliest convenience to check for real-time availability. Reservations for Christmas Eve are in exceptionally high demand and are often booked months in advance."
          }
        },
        {
          "id": "step_1_num",
          "type": "Text",
          "properties": {
            "text": "1.",
            "style": "headline"
          }
        },
        {
          "id": "step_2",
          "type": "ListItem",
          "properties": {
            "leading": {
              "id": "step_2_num"
            },
            "primary": "Provide Booking Details",
            "secondary": "If a table is available, provide the details above (date, time, party size) and use the reference ID. You will likely need to provide a primary contact name, phone number, email, and a credit card to secure the booking."
          }
        },
        {
          "id": "step_2_num",
          "type": "Text",
          "properties": {
            "text": "2.",
            "style": "headline"
          }
        },
        {
          "id": "step_3",
          "type": "ListItem",
          "properties": {
            "leading": {
              "id": "step_3_num"
            },
            "primary": "Confirm Your Requests",
            "secondary": "Reiterate your preference for a quiet table and inquire about menu options for the evening."
          }
        },
        {
          "id": "step_3_num",
          "type": "Text",
          "properties": {
            "text": "3.",
            "style": "headline"
          }
        },
        {
          "id": "step_4",
          "type": "ListItem",
          "properties": {
            "leading": {
              "id": "step_4_num"
            },
            "primary": "Finalize Menu & Budget",
            "secondary": "Discuss the menu for Christmas Eve and confirm pricing to ensure it aligns with your group's budget of €400 per person."
          }
        },
        {
          "id": "step_4_num",
          "type": "Text",
          "properties": {
            "text": "4.",
            "style": "headline"
          }
        },
        {
          "id": "actions_divider",
          "type": "Divider"
        },
        {
          "id": "quick_actions_header",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "label"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "call_button"
              },
              {
                "id": "map_button"
              }
            ]
          }
        },
        {
          "id": "call_button",
          "type": "Button",
          "properties": {
            "label": "Call L'Ambroisie to Confirm",
            "style": "filled",
            "leadingIcon": "call",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "args": {
                "url": "tel:+33142785145"
              }
            }
          }
        },
        {
          "id": "map_button",
          "type": "Button",
          "properties": {
            "label": "View on Map",
            "style": "outlined",
            "leadingIcon": "map",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "args": {
                "url": "https://www.google.com/maps/search/?api=1&query=L'Ambroisie+9+Place+des+Vosges+Paris"
              }
            }
          }
        },
        {
          "id": "sources_divider",
          "type": "Divider"
        },
        {
          "id": "sources_header",
          "type": "Text",
          "properties": {
            "text": "Sources",
            "style": "label"
          }
        },
        {
          "id": "source_link",
          "type": "Button",
          "properties": {
            "label": "Michelin Guide - L'Ambroisie",
            "style": "text",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "args": {
                "url": "https://guide.michelin.com/en/ile-de-france/paris/restaurant/l-ambroisie"
              }
            }
          }
        }
      ]
    }
  }
]
